const commits = $('Fetch Commits').all().flatMap(item => item.json);
const issues = $('Fetch Closed Issues').all().flatMap(item => item.json);
const pulls = $('Fetch Merged PRs').all().flatMap(item => item.json).filter(pr => pr.merged_at);

// Filter to last 7 days
const weekAgo = new Date();
weekAgo.setDate(weekAgo.getDate() - 7);

const recentCommits = commits.filter(c => new Date(c.commit.author.date) >= weekAgo);
const recentIssues = issues.filter(i => i.closed_at && new Date(i.closed_at) >= weekAgo);
const recentPRs = pulls.filter(p => new Date(p.merged_at) >= weekAgo);

// Build data object
const data = {
  repo: $vars.GITHUB_REPO,
  week: weekAgo.toISOString().split('T')[0] + ' to ' + new Date().toISOString().split('T')[0],
  commits: recentCommits.map(c => ({
    message: c.commit.message.split('\n')[0],
    author: c.commit.author.name,
    date: c.commit.author.date.split('T')[0]
  })),
  closedIssues: recentIssues.map(i => ({
    title: i.title,
    number: i.number,
    labels: i.labels.map(l => l.name)
  })),
  mergedPRs: recentPRs.map(p => ({
    title: p.title,
    number: p.number,
    author: p.user.login,
    additions: p.additions,
    deletions: p.deletions
  }))
};

return [{ json: data }];

const data = $input.first().json;

const lang = ($vars.LANGUAGE || 'EN').toUpperCase();
const prompts = {
  EN: `You are a senior engineering manager writing a weekly dev summary.

Repo: ${data.repo}
Week: ${data.week}

Commits (${data.commits.length}):
${data.commits.map(c => '- ' + c.message + ' (' + c.author + ')').join('\n')}

Closed Issues (${data.closedIssues.length}):
${data.closedIssues.map(i => '- #' + i.number + ' ' + i.title).join('\n')}

Merged PRs (${data.mergedPRs.length}):
${data.mergedPRs.map(p => '- #' + p.number + ' ' + p.title + ' (+' + p.additions + '/-' + p.deletions + ' by ' + p.author + ')').join('\n')}

Write a 3-4 paragraph narrative summary. Cover: what shipped, key technical changes, and what's coming next based on patterns you see. Be specific, not generic.`,
  FR: `Vous êtes un directeur technique rédigeant un résumé hebdomadaire.

Dépôt: ${data.repo}
Semaine: ${data.week}

Commits (${data.commits.length}):
${data.commits.map(c => '- ' + c.message + ' (' + c.author + ')').join('\n')}

Issues fermées (${data.closedIssues.length}):
${data.closedIssues.map(i => '- #' + i.number + ' ' + i.title).join('\n')}

PRs fusionnées (${data.mergedPRs.length}):
${data.mergedPRs.map(p => '- #' + p.number + ' ' + p.title + ' (+' + p.additions + '/-' + p.deletions + ' par ' + p.author + ')').join('\n')}

Rédigez un résumé narratif de 3-4 paragraphes. Couvrez: ce qui a été livré, les changements techniques clés, et les perspectives.`
};

return [{ json: { prompt: prompts[lang] || prompts.EN, repo: data.repo } }];

const response = $input.first().json;
const text = response.content.filter(b => b.type === 'text').map(b => b.text).join('\n');
const repo = $('Build Prompt').first().json.repo;
const summary = `# Weekly Dev Summary: ${repo}\n\n${text}`;
return [{ json: { summary } }];
